  's6705140042_kiosk'@'localhost', 's6705140042_kiosk'@'%',
  's6705140042_intern'@'%', 's6705140042_intern'@'localhost',
  's6705140042_etl'@'localhost', 's6705140042_etl'@'%',
  's6705140042_report'@'localhost', 's6705140042_report'@'%';

